const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define the two points with small buffers
  const point1 = ee.Geometry.Point([−79.198692, 43.244129]);
  const point2 = ee.Geometry.Point([−79.069485, 43.263113]);
  const buffer = 500; // 500m buffer around each point
  const geom1 = point1.buffer(buffer);
  const geom2 = point2.buffer(buffer);

  // Date of interest
  const date = '2021-02-04';
  const startDate = '2021-02-01';
  const endDate = '2021-02-07';

  // Sentinel-2 collection with cloud masking
  let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(startDate, endDate)
    .filterBounds(geom1.union(geom2));

  const colSize = col.size().getInfo();
  print(`S2 Images in range: ${colSize}`);

  if (colSize === 0) {
    print("No Sentinel-2 images found for date range.");
    print("C1");
    return;
  }

  // Cloud mask function
  function maskClouds(img) {
    const qa = img.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return img.updateMask(mask);
  }

  // Calculate NDVI
  function calcNDVI(img) {
    const ndvi = img.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return img.addBands(ndvi);
  }

  col = col.map(maskClouds).map(calcNDVI);

  // Get median composite
  const composite = col.median();

  // Extract NDVI for both points
  const ndvi1Result = composite.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geom1,
    scale: 1000,
    maxPixels: 1e9
  });

  const ndvi2Result = composite.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geom2,
    scale: 1000,
    maxPixels: 1e9
  });

  // Get pixel counts to detect valid data
  const count1 = composite.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom1,
    scale: 1000,
    maxPixels: 1e9
  });

  const count2 = composite.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom2,
    scale: 1000,
    maxPixels: 1e9
  });

  const ndvi1 = ndvi1Result.get('NDVI').getInfo();
  const ndvi2 = ndvi2Result.get('NDVI').getInfo();
  const pixels1 = count1.get('NDVI').getInfo();
  const pixels2 = count2.get('NDVI').getInfo();

  print(`Point1 NDVI: ${ndvi1 !== null ? ndvi1.toFixed(3) : 'null'}, Pixels: ${pixels1}`);
  print(`Point2 NDVI: ${ndvi2 !== null ? ndvi2.toFixed(3) : 'null'}, Pixels: ${pixels2}`);

  // Validation
  if (pixels1 === 0 || pixels2 === 0) {
    print("No valid pixels after cloud masking.");
    print("C2");
    return;
  }

  if (ndvi1 === null || ndvi2 === null || isNaN(ndvi1) || isNaN(ndvi2)) {
    print("Invalid NDVI calculation.");
    print("C3");
    return;
  }

  if (ndvi1 > ndvi2) {
    print("Point 1 is greener than Point 2.");
    print("A");
  } else {
    print("Point 1 is not greener than Point 2.");
    print("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
